sys_script_include.script:
var LabTestUtils = Class.create();
LabTestUtils.prototype = {
    initialize: function() {
        this.source = new GlideRecord('u_lab_test');
    },

    fetchLabTestResultsByTestId: function(testId) {
        this.source.get(testId);
        return this.source.u_results;
    },

    checkResults: function(testId) {
        this.source.get(testId);
        return this.source.u_status == 'completed';
    },

    fetchLabTestByPatientId: function(patId) {
        this.source.addQuery('u_patient_id', patId);
        this.source.query();
		return this.source;
    },

	fetchLabTestByDate : function(dateStr){
		this.source.addQuery('u_scheduled_date', dateStr);
		this.source.query();
		return this.source;

	},

    type: 'LabTestUtils'
};
